# Prices in USD per million tokens (input, output)
PRICES = {
    "claude-opus-5-5": (4.00, 20.00),
    "claude-sonnet-5-5": (2.00, 10.00),
    "claude-haiku-5-5": (0.10, 0.50),  # prompts up to 100K tokens
}

def cost_usd(model, input_tokens, output_tokens):
    price_in, price_out = PRICES[model]
    return (input_tokens * price_in + output_tokens * price_out) / 1_000_000

# A support chatbot: 2,000 tokens in, 500 tokens out, 10,000 requests per day
for model in PRICES:
    per_day = cost_usd(model, 2_000, 500) * 10_000
    print(f"{model}: {per_day:.2f} USD per day")

# Pick the model per task: start strong, then test cheaper models on your own examples
MODEL_FOR_TASK = {
    "classify_ticket": "claude-haiku-5-5",   # high volume, simple task: cheap and fast
    "answer_customer": "claude-sonnet-5-5",  # good quality at a mid price
    "review_contract": "claude-opus-5-5",    # long documents, hard reasoning
}

def pick_model(task: str) -> str:
    # Unknown task: fall back to the default, strongest general model
    return MODEL_FOR_TASK.get(task, "claude-opus-5-5")

print(pick_model("classify_ticket"))  # claude-haiku-5-5

# pip install anthropic
# The key is read from the ANTHROPIC_API_KEY environment variable (never hard-code it).
import anthropic

client = anthropic.Anthropic()

response = client.messages.create(
    model="claude-opus-5-5",
    max_tokens=4096,
    system="You are a patient teacher. Answer in Tunisian Derja.",
    messages=[
        {"role": "user", "content": "Explain what a token is in two sentences."}
    ],
)

if response.stop_reason == "refusal":
    print("The model refused this request.")
else:
    for block in response.content:
        if block.type == "text":
            print(block.text)
    if response.stop_reason == "max_tokens":
        print("Warning: the answer was cut, increase max_tokens.")

print("input tokens:", response.usage.input_tokens)
print("output tokens:", response.usage.output_tokens)

